 [StructLayout(LayoutKind.Sequential)]struct RectWin{public int Left,Top,Right,Bottom;}
 [DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr h,out RectWin r);
 static int checks,failures;static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).SetValue(o,v);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance).Invoke(o,a);}
 static void Check(string n,bool v){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}
 static void Pump(int ms=150){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
 static T Find<T>(DependencyObject o,Func<T,bool> match)where T:DependencyObject{var item=o as T;if(item!=null&&match(item))return item;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++){var found=Find<T>(VisualTreeHelper.GetChild(o,i),match);if(found!=null)return found;}return null;}
 static T Named<T>(DependencyObject root,string name)where T:DependencyObject{var found=Find<T>(root,x=>System.Windows.Automation.AutomationProperties.GetName(x)==name);if(found==null)throw new Exception("Missing control "+name);return found;}
 static void Click(DependencyObject root,string text){var b=Find<Button>(root,x=>Convert.ToString(x.Content)==text);if(b==null)throw new Exception("Missing button "+text);b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}
 static void Shot(Window w,string file){Pump();w.UpdateLayout();var root=(FrameworkElement)w.Content;var bitmap=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(root);var p=new PngBitmapEncoder();p.Frames.Add(BitmapFrame.Create(bitmap));using(var f=File.Create(file))p.Save(f);}
 static void PetClick(Window pet,bool twice){var down=new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,0,System.Windows.Input.MouseButton.Left){RoutedEvent=UIElement.MouseLeftButtonDownEvent};typeof(System.Windows.Input.MouseButtonEventArgs).GetProperty("ClickCount").SetValue(down,twice?2:1,null);Call(pet,"OnDown",Get(pet,"sprite"),down);Call(pet,"OnUp",Get(pet,"sprite"),new System.Windows.Input.MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,0,System.Windows.Input.MouseButton.Left){RoutedEvent=UIElement.MouseLeftButtonUpEvent});Pump();}

 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);pet.Show();Pump(300);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();((System.Threading.Timer)Get(pet,"assistantTimer")).Dispose();((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.CardShade=.38;PetClick(pet,false);Check("single click no longer opens details",Get(pet,"monitorCard")==null);PetClick(pet,true);var card=(MonitorCard)Get(pet,"monitorCard");Check("double click opens owned details",card!=null&&card.IsVisible&&card.Owner==pet);Check("details use custom chrome and detective art",card.AllowsTransparency&&card.Content is Border);
 var fake=new NetworkExit{Ip="203.0.113.5",Country="United States",CountryCode="US",Region="示例地区",City="示例城市",Isp="示例 ISP",CheckedUtc=DateTime.UtcNow};Call(card,"ShowExit",fake);Check("country code loads actual local flag pixels",((Image)Get(card,"flag")).Source!=null);fake.CountryCode="../";Call(card,"ShowExit",fake);Check("invalid or absent country uses neutral placeholder",((Image)Get(card,"flag")).Source==null);fake.CountryCode="US";Call(card,"ShowExit",fake);((TextBlock)Get(card,"exitState")).Text="界面验收示例 · 非真实出口或 VPN 状态";
 SystemSample sample=null;for(int i=0;i<20;i++){sample=new SystemSample{Utc=DateTime.UtcNow.AddSeconds(i*3),Cpu=61,MemoryUsed=8,MemoryTotal=16,Gpu=40,CpuTemperature=47,GpuTemperature=41,DiskBusy=12,Download=(Math.Sin(i*.4)+1.1)*1048576,Upload=(Math.Cos(i*.4)+1.1)*100000,NetworkName="演示网卡 · 全部为界面验收示例",TemperatureState="示例传感器数据"};card.Update(sample);}Shot(card,Path.Combine(args[0],"details-native.png"));card.Close();Pump();
 Call(pet,"OpenTerminal");var terminal=(TerminalWindow)Get(pet,"terminal");terminal.ShowPage("监控与预警");terminal.UpdateLayout();Check("monitor controls grouped into four sections",Find<Button>(terminal,b=>Convert.ToString(b.Content)=="显示与详情")!=null&&Find<Button>(terminal,b=>Convert.ToString(b.Content)=="资源预警")!=null);Check("details background choice is directly visible",Find<Button>(terminal,b=>Convert.ToString(b.Content)=="选择详情背景图…")!=null);Shot(terminal,Path.Combine(args[0],"monitor-settings-native.png"));terminal.ShowPage("任务栏外观");terminal.UpdateLayout();var screens=Named<ComboBox>(terminal,"显示在哪块屏幕");Check("taskbar screen selection lists connected monitors",screens.Items.Count==System.Windows.Forms.Screen.AllScreens.Length+1);screens.SelectedIndex=1;Click(terminal,"间距与留白");Named<Slider>(terminal,"左侧留白（0–60）滑块").Value=18;Named<Slider>(terminal,"右侧留白（0–60）滑块").Value=24;Named<Slider>(terminal,"顶部留白（0–30）滑块").Value=3;Named<Slider>(terminal,"底部留白（0–30）滑块").Value=5;var draft=(MonitorConfig)Get(terminal,"taskbarDraft");Check("four independent margins update from sliders",draft.Appearance.PaddingLeft==18&&draft.Appearance.PaddingRight==24&&draft.Appearance.PaddingTop==3&&draft.Appearance.PaddingBottom==5);Named<TextBox>(terminal,"左侧留白（0–60）").Text="12";Check("numeric input synchronizes its slider",Named<Slider>(terminal,"左侧留白（0–60）滑块").Value==12);Check("preview changes do not overwrite runtime",assistant.Config.Monitor.Appearance.PaddingLeft!=12);Shot(terminal,Path.Combine(args[0],"spacing-native.png"));Click(terminal,"应用并保存任务栏外观");var restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check("screen and asymmetric margins survive reload",restored.Config.Monitor.TaskbarScreen==System.Windows.Forms.Screen.AllScreens[0].DeviceName&&restored.Config.Monitor.Appearance.PaddingRight==24);restored.Telemetry.Dispose();Click(terminal,"布局与屏幕");Shot(terminal,Path.Combine(args[0],"screen-layout-native.png"));
 string note;Check("current primary taskbar can be resolved",TaskbarMonitor.TaskbarFor("",out note)!=IntPtr.Zero);assistant.Config.Monitor.TaskbarScreen="disconnected-screen-test";Set(terminal,"taskbarDraft",null);terminal.ShowPage("任务栏外观");terminal.UpdateLayout();Click(terminal,"布局与屏幕");var disconnected=Named<ComboBox>(terminal,"显示在哪块屏幕");Check("disconnected selection stays visible in settings",Convert.ToString(disconnected.SelectedItem).Contains("已断开"));Click(terminal,"应用并保存任务栏外观");Check("saving other appearance settings retains disconnected display",assistant.Config.Monitor.TaskbarScreen=="disconnected-screen-test");Check("disconnected display falls back explicitly",TaskbarMonitor.TaskbarFor("missing-display-test",out note)!=IntPtr.Zero&&note.Contains("未连接"));var source=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"detective-console-background-v1.png");byte[] before=File.ReadAllBytes(source);string imported=MonitorCard.ImportBackground(source,UserData.DirectoryFor(AppDomain.CurrentDomain.BaseDirectory));Check("custom art copied into stable user data",File.Exists(imported)&&imported.StartsWith(UserData.DirectoryFor(AppDomain.CurrentDomain.BaseDirectory)));Check("background import preserves source",before.SequenceEqual(File.ReadAllBytes(source)));assistant.Config.Monitor.CardBackground=imported;assistant.Save();restored=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check("custom background survives profile reload",restored.Config.Monitor.CardBackground==imported);restored.Telemetry.Dispose();
 var cfg=assistant.Config.Monitor;cfg.Appearance=TaskbarAppearance.Preset("紧凑双行");cfg.Appearance.Graphs=true;cfg.Appearance.Transparent=false;cfg.Appearance.AutoTheme=false;cfg.Appearance.LabelColor="#DFE8F4";cfg.Appearance.ValueColor="#FFFFFF";cfg.Appearance.Background="#131E2C";cfg.Appearance.GraphColor="#32526B";cfg.TaskbarItems=new System.Collections.Generic.List<string>{"cpu","memory","cpuTemp","gpuTemp","download","upload"};cfg.Taskbar=true;cfg.TaskbarScreen="";cfg.TaskbarSide="right";var bar=(TaskbarMonitor)Get(pet,"taskbarMonitor");bar.Update(sample,cfg);Pump();RectWin rect;GetWindowRect(bar.Handle,out rect);using(var bitmap=new System.Drawing.Bitmap(rect.Right-rect.Left,rect.Bottom-rect.Top)){using(var g=System.Drawing.Graphics.FromImage(bitmap))g.CopyFromScreen(rect.Left,rect.Top,0,0,bitmap.Size);bitmap.Save(Path.Combine(args[0],"taskbar-native.png"));}using(var bitmap=TaskbarPainter.Preview(cfg,sample))bitmap.Save(Path.Combine(args[0],"taskbar-preview.png"));Check("compact taskbar has managed visible state",bar.Visible);int verifiedScreens=0;foreach(var screen in System.Windows.Forms.Screen.AllScreens){string screenNote;var target=TaskbarMonitor.TaskbarFor(screen.DeviceName,out screenNote);if(target==IntPtr.Zero)continue;cfg.TaskbarScreen=screen.DeviceName;bar.Update(sample,cfg);Pump();RectWin actual;GetWindowRect(bar.Handle,out actual);bool inside=actual.Left>=screen.Bounds.Left&&actual.Right<=screen.Bounds.Right&&actual.Top>=screen.Bounds.Top&&actual.Bottom<=screen.Bounds.Bottom;Check("native taskbar matches selected screen "+screen.DeviceName,bar.Visible&&inside);if(inside)verifiedScreens++;}File.WriteAllText(Path.Combine(args[0],"screen-verification.json"),"{\"connected_screens\":"+System.Windows.Forms.Screen.AllScreens.Length+",\"native_taskbar_screens_verified\":"+verifiedScreens+",\"hotplug_verified\":false}");Check("offline flag collection bundled",Directory.GetFiles(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"flags"),"*.png").Length>=240);
 }catch(Exception e){Console.WriteLine(e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"design-results.json"),"{\"checks\":"+checks+",\"failures\":"+failures+"}");Console.WriteLine("Checks "+checks+" Failures "+failures);return failures==0?0:1;}
